  "explain": "📖 교재 근거 (교재: L3589):\n> 해설: 신속보고는 중대한 유해사례 등에 대해 안전성 정보를 알게 된 날로부터 15일 이내 식품의약품안전처장에게 보고해야 한다. 정기보고는 매 반기 종료 후 1개월 이내(1월 또는 7월)이다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
