  "explain": "📖 법령 근거 (L953(제20901호)(20260402)/화장품법(법률)(제20901호)(20260402).md#L953>)):\n제37조(벌칙) ① 제14조제4항에 따른 중지명령에 따르지 아니한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다. ② 제1항의 징역형과 벌금형은 이를 함께 부과할 수 있다.",
