  "explain": "📖 교재 근거 (교재: L1657):\n> 해설: 기능성화장품 심사 제출 서류는 효능·효과 증명 자료, 전성분 및 함량, 심사 수수료 납부 확인서 등이다. CGMP 관련 서류는 제조업 등록 시 제출하는 것이다.\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*",
