  "stem": "화장품의 표시·광고를 실증하지 못하여 식약처장으로부터 '표시·광고 중지 명령'을 받았음에도 이를 위반하여 계속 표시·광고를 한 자에 대한 처벌 기준으로 옳은 것을 모두 고른 것은?",
