  "explain": "📖 교재 근거 (교재: L451):\n| 화장품 제조업 | 화장품의 전부 또는 일부를 제조(2차 포장 또는 표시만의 공정은 제외)하는 영업<br>• 화장품을 직접 제조하는 영업<br>• 화장품 제조를 위탁받아 제조하는 영업<br>• 화장품을 포장(1차 포장만 해당)하는 영업 |",
