    "conceptId": "화장품법:제2조",
    "text": "“직접구매 해외화장품”이란 개인이 자가소비를 목적으로 해외의 사이버몰(컴퓨터 등과 정보통신설비를 이용하여 재화 등을 거래할 수 있도록 설정된 가상의 영업장을 말한다)에서 직접 구매하는 화장품을 말한다.",
