    "sid": "law_refst_3de1c5",
    "conceptId": "화장품법:제2조",
    "text": "\"맞춤형화장품판매업\"이란 화장품이 제조된 날부터 적절한 보관 상태에서 제품이 고유의 특성을 간직한 채 소비자가 안정적으로 사용할 수 있는 최소한의 기한을 말한다.",
