    "text": "우수화장품 제조관리기준 적용을 위한 시설ㆍ설비 등 개수ㆍ보수화장품법 시행규칙[제목개정 2019. 3. 14.][제12조에서 이동, 종전 제11조는 제12조로 이동 <2020. 3. 13.>]",
