    "conceptId": "화장품법 시행규칙:제11조",
    "text": "제조 또는 품질검사를 위탁하는 경우 제조 또는 품질검사가 적절하게 이루어지고 있는지 수탁자에 대한 관리ㆍ감독을 철저히 하고, 제조 및 품질관리에 관한 기록을 받아 유지ㆍ관리할 것",
